def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def = sum(1 for x in opp if x == 'D')
    my_def = sum(1 for x in my if x == 'D')
    last_my, last_opp = history[-1]
    if opp_def == n:
        return 'D'
    if opp_def == 0:
        if my_def == 0:
            if n < 2:
                return 'C'
            if n == 2:
                return 'D'
            return 'C'
        else:
            if n == 3:
                return 'C'
            return 'D'
    if last_opp == 'D':
        if opp_def <= 2 and n <= 6:
            return 'C'
        if opp_def <= 2 and my_def > 2 and n >= 10:
            return 'C'
        if opp_def <= 2 and n >= 10 and rng.random() < 0.3:
            return 'C'
        return 'D'
    else:
        if last_my == 'D':
            if n < 95 and opp_def <= 3:
                return 'D'
            return 'C'
        else:
            recent = opp[-10:] if n >= 10 else opp
            recent_def = sum(1 for x in recent if x == 'D')
            if recent_def >= 4:
                return 'D'
            return 'C'
